def find_spanning_tree_with_degree():
    import sys
    input = sys.stdin.read
    data = input().strip().split()

    n, m, D = int(data[0]), int(data[1]), int(data[2])
    edges = []

    for i in range(m):
        v, u = int(data[3 + 2 * i]), int(data[3 + 2 * i + 1])
        edges.append((v, u))

    if D >= n:
        print("NO")
        return

    from collections import defaultdict, deque

    adj = defaultdict(list)
    available = set()

    for v, u in edges:
        if v == 1 or u == 1:
            available.add((v, u))
        else:
            adj[v].append(u)
            adj[u].append(v)

    if len(available) < D:
        print("NO")
        return

    spanning_tree = []
    used = set()
    degree = 0

    for _ in range(D):
        v, u = available.pop()
        spanning_tree.append((v, u))
        used.add(v)
        used.add(u)
        if v == 1:
            degree += 1
        else:
            degree += 1

    q = deque()
    for i in range(2, n+1):
        if i not in used:
            q.append(i)

    visited = set(used)
    count = len(used)

    while q:
        curr = q.popleft()
        if curr in visited:
            continue
        visited.add(curr)
        count += 1

        for neighbor in adj[curr]:
            if neighbor not in visited:
                spanning_tree.append((curr, neighbor))
                visited.add(neighbor)
                q.append(neighbor)
                count += 1
                break

    if count == n:
        print("YES")
        for v, u in spanning_tree:
            print(v, u)
    else:
        print("NO")

