    input = sys.stdin.read
    data = input().strip().split('\n')

    grid = [list(map(int, data[i].split())) for i in range(4)]
    move = int(data[4])

    def move_line(line):
        # Slide non-zero elements to the left
        filtered = [x for x in line if x != 0]
        # Merge the adjacent equal numbers
        merged = []
        skip = False
        for i in range(len(filtered)):
            if skip:
                skip = False
                continue
            if i + 1 < len(filtered) and filtered[i] == filtered[i + 1]:
                merged.append(filtered[i] * 2)
                skip = True
            else:
                merged.append(filtered[i])
        # Fill the rest with zeros
        merged.extend([0] * (4 - len(merged)))
        return merged

    def move_left(grid):
        return [move_line(row) for row in grid]

    def move_right(grid):
        return [move_line(row[::-1])[::-1] for row in grid]

    def move_up(grid):
        transposed = zip(*grid)
        moved = [move_line(list(row)) for row in transposed]
        return [list(row) for row in zip(*moved)]

    def move_down(grid):
        transposed = zip(*grid)
        moved = [move_line(list(row)[::-1])[::-1] for row in transposed]
        return [list(row) for row in zip(*moved)]

    if move == 0:
        result = move_left(grid)
    elif move == 1:
        result = move_up(grid)
    elif move == 2:
        result = move_right(grid)
    elif move == 3:
        result = move_down(grid)

    for row in result:
