def run_length_encoding():
    import sys
    input = sys.stdin.read().strip()

    def encode(message):
        if not message:
            return ""
        encoded = []
        prev_char = message[0]
        count = 1
        for char in message[1:]:
            if char == prev_char:
                count += 1
            else:
                encoded.append(f"{prev_char}{count}")
                prev_char = char
                count = 1
        encoded.append(f"{prev_char}{count}")
        return ''.join(encoded)

    def decode(message):
        decoded = []
        for i in range(0, len(message), 2):
            char = message[i]
            count = int(message[i+1])
            decoded.append(char * count)
        return ''.join(decoded)

    mode, message = input.split(' ', 1)
    if mode == 'E':
        print(encode(message))
    elif mode == 'D':
        print(decode(message))
