    for i in range(n):
        count_first = count_second = 0
        for j in range(n):
            if i != j:
                if friends[i][0] in friends[j]:
                    count_first += 1
                if friends[i][1] in friends[j]:
                    count_second += 1
        if count_first == 1 or count_second == 1:
