    if count_first == 1:
        first_kid = friends[i][0]
        second_kid = friends[i][1]
    else:
        first_kid = friends[i][1]
        second_kid = friends[i][0]

    # Build the circle
    circle = [i + 1 for i in range(n)]
    circle[0] = first_kid
    circle[1] = second_kid

