        items.append((name, units, cost))

    def is_close(a, b, tol=1e-6):
        return abs(a - b) < tol

    def dp(i, remaining_money, remaining_units, current_selection):
        if is_close(remaining_money, 0) and is_close(remaining_units, 0):
            return current_selection
        if i >= len(items) or remaining_money < 0 or remaining_units < 0:
            return None

        name, units, cost = items[i]

        # Option 1: Don't take this item
        result = dp(i + 1, remaining_money, remaining_units, current_selection)
        if result is not None:
            return result

        # Option 2: Take this item
        take_result = dp(i, remaining_money - cost, remaining_units - units, current_selection.copy())
        if take_result is not None:
            if name in take_result:
                take_result[name] += 1
            else:
                take_result[name] = 1
            return take_result

        return None

    result = dp(0, m, u, {})

    if result is None:
        print("IMPOSSIBLE")
    else:
        for name in result:
