    # Knapsack DP
    dp = [[(-1, None) for _ in range(int(m * 100) + 1)] for _ in range(n + 1)]
    dp[0][0] = (0, None)  # (units of alcohol, prev_index)

    for i in range(n):
        name, strength, size, cost = drinks[i]
        alcohol_units = strength * size

        for spent in range(int(m * 100) + 1):
            if dp[i][spent][0] != -1:  # If there's a valid state
                # Not taking the drink
                if dp[i + 1][spent][0] < dp[i][spent][0]:
                    dp[i + 1][spent] = dp[i][spent]

