def max_distance_to_maintain_convexity():
    import sys
    input = sys.stdin.read
    from math import sqrt, isclose

    data = input().split()
    n = int(data[0])
    coords = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(n)]

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def distance(a, b):
        return sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2)

    def calculate_d(a, b, c):
        ab = distance(a, b)
        bc = distance(b, c)
        ac = distance(a, c)
        s = (ab + bc + ac) / 2
        area = sqrt(s * (s - ab) * (s - bc) * (s - ac))
        if isclose(area, 0):
            return float('inf')
        radius = (ab * bc * ac) / (4 * area)
        return radius

    max_d = float('inf')
    for i in range(n):
        a, b, c = coords[i], coords[(i+1) % n], coords[(i+2) % n]
        if cross(a, b, c) < 0:
            max_d = min(max_d, calculate_d(a, b, c))

