            # Check if a transition from one row state to another is valid
            full_mask = (1 << n) - 1
            while True:
                # Find the first position where the two masks differ
                diff = (~from_mask & to_mask & full_mask) | (from_mask & ~to_mask & full_mask)
                if diff == 0:
                    return True
                shift = diff & -diff
                position = (shift - 1).bit_length()

                if position < n - 1:
                    # Check if we can place a 1x2 (horizontal domino) macaron
                    if (from_mask & (1 << position)) == 0 and (from_mask & (1 << (position + 1))) == 0:
                        from_mask |= (3 << position)
                    else:
                        return False
                elif position < n:
                    # Check if we can place a 2x1 (vertical domino) macaron
                    if (from_mask & (1 << position)) == 0:
                        from_mask |= (1 << position)
                    else:
                        return False
                else:
                    return False

        transition_matrix = [[0] * size for _ in range(size)]

        for from_mask in range(size):
            for to_mask in range(size):
                if can_transition(from_mask, to_mask):
                    transition_matrix[from_mask][to_mask] = 1

        return transition_matrix

    transition_matrix = generate_transition_matrix(N)
    result_matrix = matrix_exponentiation(transition_matrix, M, 1 << N)

