def number_of_tilings():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    MOD = 10**9

    def matrix_mult(A, B, mod):
        """ Multiplies two matrices A and B under modulo mod. """
        return [[sum(A[i][k] * B[k][j] for k in range(len(A))) % mod for j in range(len(B[0]))] for i in range(len(A))]

    def matrix_pow(mat, exp, mod):
        """ Exponentiates matrix mat to the power of exp under modulo mod. """
        size = len(mat)
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = mat
        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2
        return result

    if N == 1:
        # For N = 1, this is a classic Fibonacci-like tiling problem
        fib = [1, 1]  # F(0) = 1, F(1) = 1
        for i in range(2, M + 1):
            fib.append((fib[-1] + fib[-2]) % MOD)
        print(fib[M])
        return

    # For larger N, we need to use the matrix exponentiation approach
    # Pre-compute the transitions for the N-row states
    def get_transitions(n):
        transitions = []
        max_state = 1 << n
        for state in range(max_state):
            fits = []
            for i in range(n):
                if state & (1 << i):
                    fits.append(False)
                else:
                    fits.append(True)
                    if i + 1 < n and not (state & (1 << (i + 1))):
                        fits.append(True)
                        i += 1
                    else:
                        fits.append(False)
            if all(fits):
                transitions.append(state)
        return transitions

    from collections import defaultdict
    state_count = 1 << N
    dp = [[0] * state_count for _ in range(2)]
    dp[0][state_count - 1] = 1  # full state

    transitions = defaultdict(list)
    for i in range(state_count):
        for j in get_transitions(N):
            if (i | j) == state_count - 1:
                transitions[i].append(j)

    current = 0
    for _ in range(M):
        next_ = 1 - current
        for j in range(state_count):
            dp[next_][j] = 0
            for prev in transitions[j]:
                dp[next_][j] = (dp[next_][j] + dp[current][prev]) % MOD
        current = next_

    print(dp[current][state_count - 1])

