def minimal_cost_of_restoration():
    import sys
    input = sys.stdin.read
    data = input().split()
    N, A, R, M = map(int, data[:4])
    h = list(map(int, data[4:]))

    if M > A + R:
        M = A + R

    def cost(target_height):
        add = remove = 0
        for height in h:
            if height < target_height:
                add += target_height - height
            else:
                remove += height - target_height
        move = min(add, remove)
        return move * M + (add - move) * A + (remove - move) * R

    left, right = 0, max(h)
    while left < right:
        mid1 = (2 * left + right) // 3
        mid2 = (left + 2 * right) // 3
        if cost(mid1) < cost(mid2):
            right = mid2
        else:
            left = mid1 + 1

    print(cost(left))

