            idx += 1

        possible = True
        result = []

        def assign_unknown_senders(messages):
            assigned = [None] * m
            for i in range(m):
                if messages[i].startswith('?:'):
                    # For an unknown message, determine possible senders
                    text = messages[i][2:].strip()
                    possible_senders = []
                    for user in usernames:
                        if not mention_check(text, user):
                            possible_senders.append(user)

                    if len(possible_senders) == 0:
                        return False, None

                    # Assign sender ensuring alternating pattern
                    if i > 0:
                        prev_sender = assigned[i-1]
                        possible_senders = [s for s in possible_senders if s != prev_sender]

                    if len(possible_senders) == 0:
                        return False, None

                    assigned[i] = possible_senders[0]  # Choose any valid sender

                else:
                    assigned[i] = messages[i].split(':')[0]

            # Verify no two consecutive same senders
            for i in range(1, m):
                if assigned[i] == assigned[i-1]:
                    return False, None

            return True, assigned

        possible, assigned_senders = assign_unknown_senders(messages)

