        count = 0
        xor_mask = 0
        masks = {0: -1}
        for i, x in enumerate(subarray):
            factors = prime_factors_count(x)
            xor_mask ^= hash(frozenset(factors.items()))
            if xor_mask in masks:
                count += 1
                masks.clear()
                xor_mask = 0
            masks[xor_mask] = i
        return count

    result = [0] * n
    for start in range(n):
        for end in range(start, n):
            subarray = A[start:end+1]
            min_group = min_groups_for_subarray(subarray)
            if min_group <= n:
                result[min_group - 1] += 1

