def sum_expressions(n, k, digits):
    MOD = 10**9 + 7

    if k == 0:
        return int(digits) % MOD

    def mod_pow(base, exp, mod):
        result = 1
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp //= 2
        return result

    factorial = [1] * (n + 1)
    inv_factorial = [1] * (n + 1)
    for i in range(2, n + 1):
        factorial[i] = factorial[i - 1] * i % MOD
    inv_factorial[n] = mod_pow(factorial[n], MOD - 2, MOD)
    for i in range(n - 1, 0, -1):
        inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % MOD

    def comb(n, r):
        if r > n or r < 0:
            return 0
        return factorial[n] * inv_factorial[r] % MOD * inv_factorial[n - r] % MOD

    total_sum = 0
    for i in range(1, n):
        if i - 1 >= k:
            coef = comb(i - 1, k) * mod_pow(10, n - 1 - i, MOD) % MOD
            total_sum = (total_sum + coef * int(digits[i])) % MOD

    for i in range(n - 1):
        if n - 2 - i >= k - 1:
            coef = comb(n - 2 - i, k - 1) * mod_pow(10, i, MOD) % MOD
            total_sum = (total_sum + coef * int(digits[i])) % MOD

    return total_sum

