def count_strings_without_agc(n):
    MOD = 10**9 + 7
    if n < 3:
        return 0

    # dp[i][a][b][c] will represent the number of valid strings of length i ending with the triplet (a, b, c)
    dp = [[[[0] * 4 for _ in range(4)] for _ in range(4)] for _ in range(n + 1)]

    # Map character to index: A=0, C=1, G=2, T=3
    char_to_index = {'A': 0, 'C': 1, 'G': 2, 'T': 3}

    # Initialize for length 3
    for a in range(4):
        for b in range(4):
            for c in range(4):
                if (a, b, c) not in [(char_to_index['A'], char_to_index['G'], char_to_index['C']),
                                     (char_to_index['A'], char_to_index['C'], char_to_index['G']),
                                     (char_to_index['G'], char_to_index['A'], char_to_index['C'])]:
                    dp[3][a][b][c] = 1

    # Fill dp table
    for i in range(4, n + 1):
        for a in range(4):
            for b in range(4):
                for c in range(4):
                    for d in range(4):
                        if (b, c, d) != (char_to_index['A'], char_to_index['G'], char_to_index['C']) and \
                           (a, c, d) != (char_to_index['A'], char_to_index['G'], char_to_index['C']) and \
                           (a, b, d) != (char_to_index['A'], char_to_index['G'], char_to_index['C']):
                            dp[i][b][c][d] = (dp[i][b][c][d] + dp[i - 1][a][b][c]) % MOD

    # Compute the result
    result = 0
    for a in range(4):
        for b in range(4):
            for c in range(4):
                result = (result + dp[n][a][b][c]) % MOD

    return result

