def count_polygons(R, C):
    from itertools import product

    def dfs(x, y, grid, visited, direction):
        if (x, y) in visited:
            return False
        visited.add((x, y))
        grid[x][y] = 1
        for dx, dy in direction:
            nx, ny = x + dx, y + dy
            if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == 0:
                if not dfs(nx, ny, grid, visited, direction):
                    return False
        return True

    def is_polygon(grid):
        for i in range(R):
            for j in range(C):
                if grid[i][j] == 0:
                    return False
        return True

    direction = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    count = 0

    for grid_state in product([0, 1], repeat=R*C):
        grid = [[0]*C for _ in range(R)]
        for idx, val in enumerate(grid_state):
            grid[idx//C][idx%C] = val

        if not is_polygon(grid):
            continue

        for i in range(R):
            for j in range(C):
                if grid[i][j] == 0:
                    continue
                visited = set()
                if dfs(i, j, grid, visited, direction) and len(visited) == sum(sum(grid, [])):
                    count += 1

    print(count)

