    from collections import deque

    # Initialize the DFA state transition table
    class DFA:
        def __init__(self):
            self.transitions = {}
            self.fail = None
            self.is_terminal = False

    dfa_root = DFA()

    # Function to insert a string into the DFA
    def insert_string(string):
        current = dfa_root
        for char in string:
            if char not in current.transitions:
                current.transitions[char] = DFA()
            current = current.transitions[char]
        current.is_terminal = True

    # Insert all taboo strings into the DFA
