        insert_string(taboo)

    # Build failure links using BFS
    queue = deque()
    for char in '01':
        if char in dfa_root.transitions:
            dfa_root.transitions[char].fail = dfa_root
            queue.append(dfa_root.transitions[char])
        else:
            dfa_root.transitions[char] = dfa_root

