                    fail_state = fail_state.fail
                failure = fail_state.transitions[char]
                current.transitions[char].fail = failure
                current.transitions[char].is_terminal |= failure.is_terminal
                queue.append(current.transitions[char])
            else:
                current.transitions[char] = current.fail.transitions[char]

    # Find the longest string
    max_length = 0
    longest_string = ''

    def dfs(node, path):
        nonlocal max_length, longest_string
        if node.is_terminal:
