        return all(all(x == p for x in row) for row in board)

    def make_move(i, j):
        for x in range(n):
            board[x][j] = 1 if board[x][j] == p else board[x][j] + 1
        for y in range(m):
            if y != j:
                board[i][y] = 1 if board[i][y] == p else board[i][y] + 1

    def revert_move(i, j):
        for x in range(n):
            board[x][j] = p if board[x][j] == 1 else board[x][j] - 1
        for y in range(m):
            if y != j:
                board[i][y] = p if board[i][y] == 1 else board[i][y] - 1

    moves = []
    def solve(move_limit):
        if is_win(board):
            return True
        if len(moves) >= move_limit:
            return False

        for i in range(n):
            for j in range(m):
                move_id = i * m + j + 1
                make_move(i, j)
                moves.append(move_id)
                if solve(move_limit):
                    return True
                moves.pop()
                revert_move(i, j)
        return False

    move_limit = p * m * n
    if solve(move_limit):
        print(len(moves))
        print(" ".join(map(str, moves)))
