        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor in edges[node]:
                    queue.append(neighbor)
        return visited

    reachable_from_1 = bfs(1, edges)
    reachable_to_2 = bfs(2, reverse_edges)

    # Intersection of nodes reachable from 1 and those that can reach 2
    valid_nodes = reachable_from_1 & reachable_to_2

    # Subgraph with only valid nodes
    subgraph_edges = defaultdict(list)
    for node in valid_nodes:
        for neighbor in edges[node]:
            if neighbor in valid_nodes:
                subgraph_edges[node].append(neighbor)

    # Detect cycle in the valid subgraph using DFS
    def has_cycle():
        visited = set()
        in_stack = set()

        def dfs(node):
            if node in in_stack:
                return True
            if node in visited:
                return False

            visited.add(node)
            in_stack.add(node)

            for neighbor in subgraph_edges[node]:
                if dfs(neighbor):
                    return True

            in_stack.remove(node)
            return False

        for node in valid_nodes:
            if node not in visited:
                if dfs(node):
                    return True
        return False

    if has_cycle():
        print("inf")
        return

    # Dynamic programming for counting paths from 1 to 2
    dp = {node: 0 for node in valid_nodes}
    dp[1] = 1

    topological_order = []
    in_degree = {node: 0 for node in valid_nodes}

    for node in valid_nodes:
        for neighbor in subgraph_edges[node]:
            in_degree[neighbor] += 1

    zero_in_degree = deque([node for node in valid_nodes if in_degree[node] == 0])

    while zero_in_degree:
        node = zero_in_degree.popleft()
        topological_order.append(node)
