def bicycle_race():
    import sys
    from collections import defaultdict, deque

    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    graph = defaultdict(list)
    rev_graph = defaultdict(list)
    edges = []

    index = 2
    for _ in range(M):
        A = int(data[index])
        B = int(data[index + 1])
        graph[A].append(B)
        rev_graph[B].append(A)
        edges.append((A, B))
        index += 2

    # Step 1: Find reachable nodes from 1 using BFS
    def reachable_from(start):
        reachable = set()
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node not in reachable:
                reachable.add(node)
                for neighbor in graph[node]:
                    queue.append(neighbor)
        return reachable

    # Step 2: Find nodes that can reach 2 using reverse BFS
    def can_reach(end):
        reachable = set()
        queue = deque([end])
        while queue:
            node = queue.popleft()
            if node not in reachable:
                reachable.add(node)
                for neighbor in rev_graph[node]:
                    queue.append(neighbor)
        return reachable

    reachable_from_1 = reachable_from(1)
    can_reach_2 = can_reach(2)

    # Step 3: Find nodes that are part of cycles using DFS and Tarjan's SCC algorithm
    def find_sccs():
        index = 0
        stack = []
        on_stack = set()
        indices = {}
        lowlink = {}
        sccs = []

        def strongconnect(v):
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack.add(v)

            for w in graph[v]:
                if w not in indices:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])

            if lowlink[v] == indices[v]:
                scc = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    scc.append(w)
                    if w == v:
                        break
                sccs.append(scc)

        for v in range(1, N+1):
            if v not in indices:
                strongconnect(v)

        return sccs

    sccs = find_sccs()
    cycle_nodes = set()
    for scc in sccs:
        if len(scc) > 1:
            cycle_nodes.update(scc)

    # Step 4: Check if any cycle node is reachable from 1 and can reach 2
    for node in cycle_nodes:
        if node in reachable_from_1 and node in can_reach_2:
            print("inf")
            return

    # Step 5: Count the number of distinct paths from 1 to 2 using DP
    dp = [0] * (N + 1)
    dp[1] = 1

    order = []
    visited = set()

    def topological_sort(v):
        visited.add(v)
        for neighbor in graph[v]:
            if neighbor not in visited:
                topological_sort(neighbor)
        order.append(v)

    topological_sort(1)
    order.reverse()

    for u in order:
        if u in reachable_from_1 and u in can_reach_2:
            for v in graph[u]:
                if v in reachable_from_1 and v in can_reach_2:
                    dp[v] += dp[u]
                    dp[v] %= 1000000000

    print(dp[2])

