def count_routes():
    import sys
    sys.setrecursionlimit(100000)
    input = sys.stdin.read
    data = input().split()

    from collections import defaultdict, deque

    N = int(data[0])
    M = int(data[1])

    graph = defaultdict(list)
    reverse_graph = defaultdict(list)
    index = 2
    for _ in range(M):
        A = int(data[index])
        B = int(data[index + 1])
        graph[A].append(B)
        reverse_graph[B].append(A)
        index += 2

    # To find if there's a path from 1 to 2
    def bfs(start, target):
        visited = [False] * (N + 1)
        queue = deque([start])
        visited[start] = True
        while queue:
            current = queue.popleft()
            if current == target:
                return True
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return False

    # Check reachability from 1 to 2
    if not bfs(1, 2):
        print(0)
        return

    # Check for cycles in the forward and reverse graph
    visited = [False] * (N + 1)
    on_stack = [False] * (N + 1)

    def has_cycle(v):
        if visited[v]:
            return False
        visited[v] = True
        on_stack[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                if has_cycle(neighbor):
                    return True
            elif on_stack[neighbor]:
                return True
        on_stack[v] = False
        return False

    # Check if there's a cycle in the graph that connects to both 1 and 2
    def check_cycles():
        cycle_found = [False]

        def dfs(v):
            if cycle_found[0]:
                return
            visited[v] = True
            on_stack[v] = True
            for neighbor in graph[v]:
                if not visited[neighbor]:
                    dfs(neighbor)
                elif on_stack[neighbor]:
                    cycle_found[0] = True
                    return
            on_stack[v] = False

        # Check from node 1
        visited[:] = [False] * (N + 1)
        on_stack[:] = [False] * (N + 1)
        dfs(1)

        if cycle_found[0]:
            return True

        # Check in the subgraph that can reach 2 (reverse graph from 2)
        visited[:] = [False] * (N + 1)
        on_stack[:] = [False] * (N + 1)

        reachable = [False] * (N + 1)

        def mark_reachable_from_target(v):
            reachable[v] = True
            for neighbor in reverse_graph[v]:
                if not reachable[neighbor]:
                    mark_reachable_from_target(neighbor)

        mark_reachable_from_target(2)

        def dfs_reverse(v):
            if cycle_found[0]:
                return
            visited[v] = True
            on_stack[v] = True
            for neighbor in graph[v]:
                if reachable[neighbor]:
                    if not visited[neighbor]:
                        dfs_reverse(neighbor)
                    elif on_stack[neighbor]:
                        cycle_found[0] = True
                        return
            on_stack[v] = False

        visited[:] = [False] * (N + 1)
        on_stack[:] = [False] * (N + 1)
        for i in range(1, N + 1):
            if reachable[i] and not visited[i]:
                dfs_reverse(i)

        return cycle_found[0]

    if check_cycles():
        print("inf")
        return

    # If no cycles, count paths
    dp = [0] * (N + 1)
    dp[1] = 1

    order = []
    visited = [False] * (N + 1)

    def topological_sort(v):
        visited[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                topological_sort(neighbor)
        order.append(v)

    topological_sort(1)
    order.reverse()

    for u in order:
        for v in graph[u]:
            dp[v] += dp[u]
            if dp[v] >= 1000000000:
                dp[v] %= 1000000000

    print(dp[2])
