def minimum_crossing_time():
    import sys
    input = sys.stdin.read
    from collections import deque

    data = input().strip().split()
    P, R, L = int(data[0]), int(data[1]), int(data[2])
    edges = []

    index = 3
    for _ in range(L):
        E1, E2 = int(data[index]), int(data[index + 1])
        edges.append((E1, E2))
        index += 2

    # Build an adjacency list for the graph
    graph = {i: [] for i in range(-2, R)}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs():
        queue = deque([-2])
        visited = set([-2])
        while queue:
            node = queue.popleft()
            if node == -1:
                return True
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    # Determine the maximum number of people who can cross
    def can_cross(k):
        visited = set()

        # Try to perform 'k' BFS traversals
        for _ in range(k):
            if not bfs():
                return False

            # Mark all edges under the current traversal as visited
            # This would remove them for subsequent traversals
            queue = deque([-2])
            current_visited = set([-2])
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if (node, neighbor) not in visited and (neighbor, node) not in visited:
                        if neighbor not in current_visited:
                            current_visited.add(neighbor)
                            queue.append(neighbor)
            # Update visited edges
            for node in current_visited:
                for neighbor in graph[node]:
                    visited.add((node, neighbor))
                    visited.add((neighbor, node))

        return True

    left, right = 0, P
    answer = 0

    while left <= right:
        mid = (left + right) // 2
        if can_cross(mid):
            answer = mid
            left = mid + 1
        else:
            right = mid - 1

    if answer == P:
        print(P * 3)
    else:
        print(f"{P - answer} people left behind")

