        node_counts[node] += 1

    def bfs(start_nodes):
        queue = collections.deque()
        distances = {}
        for node, count in start_nodes.items():
            queue.append((node, 0))
            distances[node] = 0

        while queue:
            current, dist = queue.popleft()

            f = lowest_prime_divisor(current)
            next_node = current // f
            if next_node not in distances or dist + 1 < distances[next_node]:
                distances[next_node] = dist + 1
                queue.append((next_node, dist + 1))

        return distances

