def min_path_sum():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = list(map(int, data[1:n+1]))

    # Precompute factorials up to 5000!
    max_k = max(k)
    factorials = [1] * (max_k + 1)
    for i in range(2, max_k + 1):
        factorials[i] = factorials[i-1] * i

    # Compute the number of fragments at each factorial node
    fragment_count = defaultdict(int)
    for ki in k:
        fragment_count[factorials[ki]] += 1

    # Dijkstra's algorithm to find the shortest paths
    # We compute shortest path tree from node 1
    def lowest_prime_divisor(x):
        if x % 2 == 0:
            return 2
        for i in range(3, int(math.sqrt(x)) + 1, 2):
            if x % i == 0:
                return i
        return x

    def get_neighbors(x):
        if x == 1:
            return []
        f_x = lowest_prime_divisor(x)
        return [x // f_x]

    # Priority queue for Dijkstra's algorithm
    queue = [(0, 1)]  # (distance, node)
    distance = {1: 0}

    while queue:
        dist, node = heappop(queue)
        if dist > distance.get(node, float('inf')):
            continue
        for neighbor in get_neighbors(node):
            alt = dist + 1
            if alt < distance.get(neighbor, float('inf')):
                distance[neighbor] = alt
                heappush(queue, (alt, neighbor))

    # Calculate the minimal path sum
    min_path_sum = 0
    for key in fragment_count:
        if key in distance:
            min_path_sum += distance[key] * fragment_count[key]

