import sys
import math
from collections import defaultdict

def find_lowest_prime_factors(limit):
    spf = list(range(limit + 1))
    p = 2
    while p * p <= limit:
        if spf[p] == p:
            for i in range(p * p, limit + 1, p):
                if spf[i] == i:
                    spf[i] = p
        p += 1
    return spf

def calculate_factorial_nodes(limit):
    factorial_nodes = [1] * (limit + 1)
    for i in range(1, limit + 1):
        factorial_nodes[i] = factorial_nodes[i - 1] * i
    return factorial_nodes

def dijkstra(start, graph, n):
    import heapq
    dist = {node: float('inf') for node in range(1, n + 1)}
    dist[start] = 0
    priority_queue = [(0, start)]
    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_distance > dist[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
    return dist

def calculate_minimal_path_sum(n, k_list):
    max_k = max(k_list)
    factorial_limit = max_k
    factorial_nodes = calculate_factorial_nodes(factorial_limit)
    spf = find_lowest_prime_factors(factorial_nodes[max_k])

    graph = defaultdict(list)
    for i in range(2, factorial_nodes[max_k] + 1):
        factor = spf[i]
        next_node = i // factor
        graph[i].append((next_node, 1))
        graph[next_node].append((i, 1))

    fragments = [factorial_nodes[k] for k in k_list]
    distance_sums = defaultdict(int)
    for fragment in fragments:
        distances = dijkstra(fragment, graph, factorial_nodes[max_k])
        for node, distance in distances.items():
            distance_sums[node] += distance

    return min(distance_sums.values())

