def prime_factors_sieve(limit):
    sieve = list(range(limit + 1))
    for start in range(2, int(limit**0.5) + 1):
        if sieve[start] == start:
            for multiple in range(start*start, limit + 1, start):
                if sieve[multiple] == multiple:
                    sieve[multiple] = start
    return sieve

def factorial_largest_below(limit):
    factorial = [1] * (limit + 1)
    for i in range(2, limit + 1):
        factorial[i] = factorial[i - 1] * i
        if factorial[i] > sys.maxsize:
            return factorial[:i]
    return factorial

