def count_guard_placements():
    import sys
    input = sys.stdin.read
    from collections import defaultdict
    import itertools

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def normalize_direction(dx, dy):
        if dx == 0 and dy == 0:
            return (0, 0)
        g = gcd(abs(dx), abs(dy))
        return (dx // g, dy // g)

    data = input().strip().split()
    N = int(data[0])
    segments = []
    idx = 1
    for _ in range(N):
        x1, y1, x2, y2 = map(int, data[idx:idx+4])
        segments.append((x1, y1, x2, y2))
        idx += 4

    point_to_segments = defaultdict(set)
    line_to_segments = defaultdict(set)

    for i, (x1, y1, x2, y2) in enumerate(segments):
        for (px, py) in [(x1, y1), (x2, y2)]:
            point_to_segments[(px, py)].add(i)

        dx, dy = x2 - x1, y2 - y1
        dir = normalize_direction(dx, dy)
        line_to_segments[(x1, y1, dir)].add(i)
        line_to_segments[(x2, y2, dir)].add(i)

    def calculate_collinear_points(x1, y1, dir):
        collinear_points = []
        seen_segments = set()
        points = [(x1, y1)]

        for (px, py) in points:
            for seg_idx in point_to_segments[(px, py)]:
                if seg_idx not in seen_segments:
                    x1, y1, x2, y2 = segments[seg_idx]
                    if normalize_direction(x2 - x1, y2 - y1) == dir:
                        if (x1, y1) != (px, py):
                            points.append((x1, y1))
                        if (x2, y2) != (px, py):
                            points.append((x2, y2))
                        seen_segments.add(seg_idx)

        return points

    valid_lines = set()

    for (x1, y1, dir), seg_indices in line_to_segments.items():
        if len(seg_indices) < 3:
            continue
        collinear_points = calculate_collinear_points(x1, y1, dir)
        if len(collinear_points) >= 3:
            valid_lines.add(frozenset(collinear_points))

    print(len(valid_lines))

