    n, s, t, q = map(int, input_data[0].split())
    hills = [tuple(map(int, line.split())) for line in input_data[1:n+1]]
    springs = list(map(int, input_data[n+1].split()))
    towns = list(map(int, input_data[n+2].split()))
    return n, s, t, q, hills, springs, towns

def distance(hill1, hill2):
    x1, y1, h1 = hill1
    x2, y2, h2 = hill2
    return math.sqrt((x1 - x2)**2 + (y1 - y2)**2 + (h1 - h2)**2)

def can_build_aqueduct(src, dest, max_length):
    return distance(src, dest) <= max_length

def construct_graph(hills, springs, towns, max_length):
    graph = [[] for _ in range(len(hills))]
    for i in springs:
        for j in towns:
            if can_build_aqueduct(hills[i-1], hills[j-1], max_length):
                graph[i-1].append((distance(hills[i-1], hills[j-1]), j-1))
    return graph

def minimum_spanning_tree(graph, s, t):
    pq = []
    visited = [False] * len(graph)
    min_cost = 0
    edges_used = 0

    # Start with any spring
    for i in range(len(graph)):
        if i in springs:
            heapq.heappush(pq, (0, i))
            break

    while pq and edges_used < t:
        cost, node = heapq.heappop(pq)
        if visited[node]:
            continue
        visited[node] = True
        min_cost += cost
        edges_used += 1

        for next_cost, neighbor in graph[node]:
            if not visited[neighbor]:
                heapq.heappush(pq, (next_cost, neighbor))

    if edges_used == t:
        return min_cost
    else:
        return float('inf')

def main():
    n, s, t, q, hills, springs, towns = read_input()
    graph = construct_graph(hills, springs, towns, q)
    min_cost = minimum_spanning_tree(graph, s, t)

    if min_cost == float('inf'):
        print("IMPOSSIBLE")
    else:
        print(f"{min_cost:.6f}")

if __name__ == "__main__":
    main()
