def count_ways(n, k):
    MOD = 1000000007

    def factorial(x):
        result = 1
        for i in range(2, x + 1):
            result = (result * i) % MOD
        return result

    def power(base, exp, mod):
        result = 1
        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % mod
            base = (base * base) % mod
            exp //= 2
        return result

    if k == 1:
        return 0
    if n == k:
        return factorial(k - 1)

    ways_for_k = factorial(k - 1)
    ways_for_remaining = power(n - k, n - k, MOD)

    return (ways_for_k * ways_for_remaining) % MOD

