    def comb(n, k, mod):
        if n < k or k < 0:
            return 0
        num = 1
        denom = 1
        for i in range(k):
            num = num * (n - i) % mod
            denom = denom * (i + 1) % mod
        return num * mod_inv(denom, mod) % mod

    power3_NMK = pow(3, N + M + K, MOD)

    result = 0
    for i in range(K + 1):
        for j in range(M + 1):
            if i + j > N:
                continue
            coeff = comb(N, i + j, MOD) * comb(i + j, i, MOD) % MOD
            power3_remainder = pow(3, N - i - j, MOD)
            result = (result + coeff * power3_remainder) % MOD

