from collections import deque

def solve_puzzle():
    target = ['RRRR', 'GGGG', 'BBBB', 'YYYY']
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]  # down, up, right, left

    def move(grid, direction, idx):
        new_grid = [list(row) for row in grid]
        if direction == (1, 0):  # move column down
            col = [grid[(i - 1) % 4][idx] for i in range(4)]
            for i in range(4):
                new_grid[i][idx] = col[i]
        elif direction == (-1, 0):  # move column up
            col = [grid[(i + 1) % 4][idx] for i in range(4)]
            for i in range(4):
                new_grid[i][idx] = col[i]
        elif direction == (0, 1):  # move row right
            row = grid[idx][-1:] + grid[idx][:-1]
            new_grid[idx] = row
        elif direction == (0, -1):  # move row left
            row = grid[idx][1:] + grid[idx][:1]
            new_grid[idx] = row
        return tuple(''.join(row) for row in new_grid)

    def bfs(start):
        queue = deque([(start, 0)])
        visited = {start}

        while queue:
            current, moves = queue.popleft()
            if current == tuple(target):
                return moves

            for d in directions:
                for idx in range(4):
                    new_grid = move(current, d, idx)
                    if new_grid not in visited:
                        visited.add(new_grid)
                        queue.append((new_grid, moves + 1))
        return -1

    initial_grid = tuple(input().strip() for _ in range(4))
    print(bfs(initial_grid))

