import sys

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def is_point_in_convex_hull(point, hull):
    low, high = 1, len(hull) - 1
    if cross(hull[0], hull[1], point) < 0 or cross(hull[0], hull[-1], point) > 0:
        return False
    while low + 1 < high:
        mid = (low + high) // 2
        if cross(hull[0], hull[mid], point) >= 0:
            low = mid
        else:
            high = mid
    return cross(hull[low], hull[high], point) >= 0

def max_onions_protected(N, M, K, onions, fence_posts):
    max_onions = 0
    for comb in combinations(fence_posts, K):
        comb = list(comb)
        hull = []
        for p in sorted(comb):
            while len(hull) >= 2 and cross(hull[-2], hull[-1], p) <= 0:
                hull.pop()
            hull.append(p)
        t = len(hull)
        for p in reversed(sorted(comb)):
            while len(hull) > t and cross(hull[-2], hull[-1], p) <= 0:
                hull.pop()
            hull.append(p)
        hull.pop()
        count = sum(is_point_in_convex_hull(onion, hull) for onion in onions)
        max_onions = max(max_onions, count)
